const GRADE_SYNONYMS = {
  '-1': 'Pre-K, PreK, Pre-Kindergarten, Prekindergarten, VPK',
  '0':  'Kindergarten, K',
  '1':  'First, 1st, 1',
  '2':  'Second, 2nd, 2',
  '3':  'Third, 3rd, 3',
  '4':  'Fourth, 4th, 4',
  '5':  'Fifth, 5th, 5',
  '6':  'Sixth, 6th, 6',
  '7':  'Seventh, 7th, 7',
  '8':  'Eighth, 8th, 8',
  '9':  'Ninth, Tenth, Eleventh, Twelfth, 9th, 10th, 11th, 12th, 9, 10, 11, 12, 9-12, High School'
};
const LANG_NAMES = { en: 'English', es: 'Spanish', ht: 'Haitian Creole' };

return $input.all().map(item => {
  const r = item.json;
  const gs = r.grade_sort === null || r.grade_sort === undefined ? '' : String(r.grade_sort);
  const langs = (r.languages || 'en').split(',').map(s => s.trim()).filter(Boolean)
    .map(c => LANG_NAMES[c] || c).join(', ');
  const theme = r.theme || (r.unit ? r.unit : '');
  return { json: {
    'Lesson ID': r.lesson_id,
    'Grade': GRADE_SYNONYMS[gs] || r.grade_label || '',
    'Grade Sort': r.grade_sort,
    'Theme / Topic': theme,
    'Lesson #': r.lesson_number,
    'Title of Lesson': r.title,
    'Summary of Lesson': r.summary,
    'Topic Tags': r.topic_tags,
    'Fundamental Concepts': r.concepts,
    'Standards (as published)': r.standards_raw,
    'Standards Framework': r.framework,
    'lessonUrl': r.lesson_url,
    'pdfUrl': r.pdf_url,
    'Status': r.status,
    'Notes': [r.machine_notes, 'Languages available: ' + langs].filter(Boolean).join(' | ')
  }};
});

// Merge run summary (always available) with optional Excel path.
const s = $('Check Run Summary').first().json;

const warn = [];
if (+s.plans_not_public  > 0) warn.push(`${s.plans_not_public} lesson plan(s) are NOT publicly shared`);
if (+s.zero_byte_files   > 0) warn.push(`${s.zero_byte_files} file(s) are 0 bytes`);
if (+s.resourcekey_files > 0) warn.push(`${s.resourcekey_files} legacy file(s) need a resourcekey`);
if (+s.review_lessons    > 0) warn.push(`${s.review_lessons} lesson(s) sitting in Under review`);

const blockers = [];
if (+s.missing_summary   > 0) blockers.push(`${s.missing_summary} lesson(s) still have no summary`);
if (+s.missing_standards > 0) blockers.push(`${s.missing_standards} lesson(s) still have no standards`);

const hadChanges = (+s.lessons_touched + +s.assets_touched) > 0;
const shouldEmail = warn.length > 0
  || +s.newly_discovered > 0
  || s.is_sunday
  || hadChanges;

const html = `
<h3>Everglades Lesson Finder - nightly index sync</h3>
<p><b>${s.active_lessons}</b> active &middot; ${s.draft_lessons} draft &middot; ${s.review_lessons} under review &middot; ${s.retired_lessons} retired</p>
${hadChanges ? '<p>Structural changes detected — master index updated.</p>' : '<p>No structural changes — master index left unchanged.</p>'}
${+s.newly_discovered > 0 ? `<p><b>${s.newly_discovered} newly discovered lesson(s)</b> added as Draft.</p>` : ''}
${warn.length ? `<p><b>Needs attention</b></p><ul>${warn.map(w => `<li>${w}</li>`).join('')}</ul>` : '<p>No file or permission problems detected.</p>'}
${blockers.length ? `<p><b>Waiting on the Education Department</b></p><ul>${blockers.map(b => `<li>${b}</li>`).join('')}</ul>` : ''}
<p><b>Language coverage:</b> Spanish ${s.lessons_with_spanish}, Haitian Creole ${s.lessons_with_creole}</p>
<details><summary>Flagged rows</summary><pre>${String(s.flagged_rows).replace(/</g,'&lt;')}</pre></details>`;

const subject = warn.length
  ? `Lesson Finder sync - ${warn.length} item(s) need attention`
  : hadChanges
    ? `Lesson Finder sync - ${s.active_lessons} active, index updated`
    : `Lesson Finder sync - ${s.active_lessons} active, all healthy`;

return [{ json: { subject, html, shouldEmail } }];

const EDUCATION = [
  'Theme / Topic',
  'Summary of Lesson',
  'Topic Tags',
  'Fundamental Concepts',
  'Standards (as published)',
  'Standards Framework',
];
const COLS = [
  'Lesson ID', 'Grade', 'Grade Sort', 'Theme / Topic', 'Lesson #',
  'Title of Lesson', 'Summary of Lesson', 'Topic Tags', 'Fundamental Concepts',
  'Standards (as published)', 'Standards Framework', 'lessonUrl', 'pdfUrl',
  'Status', 'Notes',
];
const MACHINE = COLS.filter(c => c !== 'Lesson ID' && !EDUCATION.includes(c));

function normId(v) {
  if (v === undefined || v === null) return '';
  return String(v).trim();
}
function idsMatch(a, b) {
  const sa = normId(a), sb = normId(b);
  if (!sa || !sb) return false;
  if (sa === sb) return true;
  const na = Number(sa), nb = Number(sb);
  return sa !== '' && sb !== '' && !Number.isNaN(na) && !Number.isNaN(nb) && na === nb;
}

const incoming = $('Shape Spreadsheet Rows').all().map(i => i.json);
const existingRaw = $input.all().map(i => i.json);
const existing = [];
const seenExisting = new Set();
for (const r of existingRaw) {
  const id = normId(r['Lesson ID']);
  if (!id || id === 'Lesson ID') continue;
  const key = Number(id) && !Number.isNaN(Number(id)) ? String(Number(id)) : id;
  if (seenExisting.has(key)) continue;
  seenExisting.add(key);
  existing.push(r);
}

const usedIncoming = new Set();
const merged = [];

for (const old of existing) {
  const inc = incoming.find(x => idsMatch(x['Lesson ID'], old['Lesson ID']));
  if (!inc) {
    merged.push(old);
    continue;
  }
  usedIncoming.add(inc);
  const row = { ...old };
  for (const k of MACHINE) {
    if (inc[k] !== undefined && inc[k] !== null && inc[k] !== '') row[k] = inc[k];
  }
  merged.push(row);
}

for (const inc of incoming) {
  if (usedIncoming.has(inc)) continue;
  if (existing.some(old => idsMatch(old['Lesson ID'], inc['Lesson ID']))) continue;
  merged.push(inc);
}

const values = [COLS, ...merged.map(r => COLS.map(c => (r[c] === undefined || r[c] === null ? '' : r[c])))];
const endRow = 4 + values.length; // header at row 5
return [{ json: { values, range: `A5:O${endRow}`, rowCount: merged.length } }];
